using Astrea.BattleActions;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "CorruptedScrappingCustomDescription", menuName = "Data/Battle/Battle Actions/BaseBattleActionData/Enemy/CorruptedScrappingCustomDescription", order = 0)]
public class CorruptedScrappingCustomDescription : CustomBattleActionDescription
{
	private const string breakCorruptedAssistantID = "BreakCorruptedAssistant";

	private const string pointOfCorruptionCorruptedAssistantID = "PointOfCorruptionCorruptedAssistant";

	public override string GetActionDescription(string amountModified, BattleAction battleAction)
	{
		CorruptedScrappingAction corruptedScrappingAction = battleAction as CorruptedScrappingAction;
		string localizedForEach = base.localizationManager.GetLocalizedForEach();
		localizedForEach = Smart.Format(localizedForEach, corruptedScrappingAction.BattleAction.GetActionDescription(GetFinalAmountWithoutEquation(amountModified)).RemoveLastIfNotJapaneseNorKoreanNorTraditionalChinese(), base.localizationManager.GetLocalizedString("PointOfCorruptionCorruptedAssistant"));
		return base.localizationManager.GetLocalizedString("BreakCorruptedAssistant") + "\n" + localizedForEach;
	}
}
